def get_valid_times(start_time, end_time):
    def increment_time(time_str):
        h, m = map(int, time_str.split(':'))
        m += 1
        if m == 60:
            m = 0
            h += 1
            if h == 24:
                h = 0
        return f"{h:02}:{m:02}"

    def decrement_time(time_str):
        h, m = map(int, time_str.split(':'))
        m -= 1
        if m == -1:
            m = 59
            h -= 1
            if h == -1:
                h = 23
        return f"{h:02}:{m:02}"

    def is_valid_time(time_str):
        h, m = map(int, time_str.split(':'))
        return 0 <= h <= 23 and 0 <= m <= 59

    start_h, start_m = map(int, start_time.split(':'))
    end_h, end_m = map(int, end_time.split(':'))

    times = set()
    current_time = start_time
    while current_time != end_time:
        times.add(current_time)
        if (start_h, start_m) < (end_h, end_m):
            current_time = increment_time(current_time)
        else:
            current_time = decrement_time(current_time)
    times.add(end_time)

    return sorted(times)

def main():
    import sys
    input = sys.stdin.read
    data = input().splitlines()
    start_time = data[0]
    end_time = data[1]

    valid_times = get_valid_times(start_time, end_time)
    print(len(valid_times))
    for time in valid_times:
        print(time)

if __name__ == "__main__":
    main()
